<?php
session_start();
require_once '../shared/config.php';
require_once '../shared/security.php';
o2oCsrfToken();
requireLogin('vendor','login.php');
$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 o2oRequireCsrf();$action=$_POST['action']??'';$itemId=(int)($_POST['item_id']??0);
 $own=$db->prepare("SELECT id,name FROM items WHERE id=? AND vendor_id=?");$own->execute([$itemId,$vendorId]);$item=$own->fetch();
 if(!$item)$error='Item not found in your inventory.';
 elseif($action==='save'){
  $label=trim($_POST['size_label']??'');$vals=[];
  foreach(['chest','waist','hip','length'] as $k){$v=(float)($_POST[$k]??0);$vals[$k]=$v>0?$v:null;}
  if($label==='')$error='Size label is required.';
  elseif(!$vals['chest']&&!$vals['waist']&&!$vals['hip']&&!$vals['length'])$error='Enter at least one measurement.';
  else{$st=$db->prepare("INSERT INTO product_sizes(item_id,size_label,chest,waist,hip,length,available) VALUES(?,?,?,?,?,?,1)");$st->execute([$itemId,$label,$vals['chest'],$vals['waist'],$vals['hip'],$vals['length']]);$message='Size chart entry added.';}
 }elseif($action==='toggle'){
  $sizeId=(int)($_POST['size_id']??0);$st=$db->prepare("UPDATE product_sizes ps JOIN items i ON i.id=ps.item_id SET ps.available=NOT ps.available WHERE ps.id=? AND ps.item_id=? AND i.vendor_id=?");$st->execute([$sizeId,$itemId,$vendorId]);$message=$st->rowCount()?'Size availability updated.':'Size entry not found.';
 }elseif($action==='delete'){
  $sizeId=(int)($_POST['size_id']??0);$st=$db->prepare("DELETE ps FROM product_sizes ps JOIN items i ON i.id=ps.item_id WHERE ps.id=? AND ps.item_id=? AND i.vendor_id=?");$st->execute([$sizeId,$itemId,$vendorId]);$message=$st->rowCount()?'Size entry removed.':'Size entry not found.';
 }
}
$itemsSt=$db->prepare("SELECT id,name FROM items WHERE vendor_id=? ORDER BY name");$itemsSt->execute([$vendorId]);$items=$itemsSt->fetchAll();
$selected=(int)($_GET['item_id']??$_POST['item_id']??($items[0]['id']??0));
$sizesSt=$db->prepare("SELECT ps.* FROM product_sizes ps JOIN items i ON i.id=ps.item_id WHERE ps.item_id=? AND i.vendor_id=? ORDER BY ps.size_label");$sizesSt->execute([$selected,$vendorId]);$sizes=$sizesSt->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Size Charts – O2O Tradition</title><style>
body{font-family:Arial;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:1050px;margin:auto;padding:30px}.card{background:#fff;padding:22px;margin-bottom:18px;box-shadow:0 2px 10px #0001}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.field label{display:block;font-size:11px;color:#777;margin-bottom:5px}.field input,.select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ddd}.btn{background:#0D4F4F;color:#fff;border:0;padding:10px 15px}.notice{padding:11px;background:#F0FDF4;color:#166534}.error{padding:11px;background:#FEF2F2;color:#991B1B}.row{display:grid;grid-template-columns:1fr repeat(4,110px) 100px 100px;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid #eee}.muted{font-size:12px;color:#777}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr 1fr}.row form{display:inline-block}}
</style></head><body><div class="nav"><div>O2O Tradition · Size Charts</div><div><a href="dashboard.php">Dashboard</a><a href="inventory.php">Inventory</a><a href="logout.php">Logout</a></div></div><main class="main"><h1>Vendor Size Charts</h1><p class="muted">Add measured garment dimensions so customers can receive product-specific size guidance.</p><?php if($message):?><div class="notice"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card"><form method="GET"><label>Item</label><select class="select" name="item_id" onchange="this.form.submit()"><?php foreach($items as $i):?><option value="<?=$i['id']?>" <?=$selected===(int)$i['id']?'selected':''?>><?=htmlspecialchars($i['name'])?></option><?php endforeach;?></select></form></div><?php if($selected):?><div class="card"><h2>Add size measurement</h2><form method="POST"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="save"><input type="hidden" name="item_id" value="<?=$selected?>"><div class="grid"><div class="field"><label>Size label *</label><input name="size_label" placeholder="M, L, 42" required></div><?php foreach(['chest','waist','hip','length'] as $k):?><div class="field"><label><?=ucfirst($k)?> (cm)</label><input type="number" name="<?=$k?>" min="0" step="0.1"></div><?php endforeach;?></div><button class="btn" style="margin-top:14px">Add to chart</button></form></div><div class="card"><h2>Current chart</h2><?php if($sizes):?><div class="row"><b>Size</b><b>Chest</b><b>Waist</b><b>Hip</b><b>Length</b><b>Status</b><b>Action</b></div><?php foreach($sizes as $s):?><div class="row"><div><b><?=htmlspecialchars($s['size_label'])?></b></div><div><?=htmlspecialchars($s['chest']??'—')?></div><div><?=htmlspecialchars($s['waist']??'—')?></div><div><?=htmlspecialchars($s['hip']??'—')?></div><div><?=htmlspecialchars($s['length']??'—')?></div><div><?=((int)$s['available']?'Available':'Hidden')?></div><div><form method="POST" style="display:inline"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="item_id" value="<?=$selected?>"><input type="hidden" name="size_id" value="<?=$s['id']?>"><button><?=((int)$s['available']?'Hide':'Show')?></button></form> <form method="POST" style="display:inline" onsubmit="return confirm('Remove this size?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="item_id" value="<?=$selected?>"><input type="hidden" name="size_id" value="<?=$s['id']?>"><button>Delete</button></form></div></div><?php endforeach;?><?php else:?><p class="muted">No measurements yet. Add the vendor's measured sizes above.</p><?php endif;?></div><?php endif;?></main></body></html>